use super::*;
use std::os::unix::fs::DirBuilderExt;
struct Fixture{path:PathBuf,parent:Arc<Directory>}
impl Fixture{fn new()->Self{let path=std::env::temp_dir().join(format!("rudder-new-namespace-data-{}",uuid::Uuid::new_v4()));fs::DirBuilder::new().mode(0o700).create(&path).unwrap();let parent=Directory::open_existing_root(path.clone()).unwrap();Self{path,parent}}}
impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.path);}}
fn settings()->jj_lib::settings::UserSettings{use jj_lib::config::{StackedConfig,ConfigLayer,ConfigSource};let mut c=StackedConfig::with_defaults();let mut l=ConfigLayer::empty(ConfigSource::User);l.set_value("user.name","Fresh source fixture").unwrap();l.set_value("user.email","fixture@invalid.example").unwrap();c.add_layer(l);jj_lib::settings::UserSettings::from_config(c).unwrap()}
#[test]
fn actual_new_directory_owner_refuses_existing_history_and_never_adopts_it(){let f=Fixture::new();fs::create_dir(f.path.join("existing")).unwrap();fs::write(f.path.join("existing/history"),b"keep").unwrap();let original=FinalizationBudget::begin(Duration::from_secs(5)).unwrap();let cancel=AtomicBool::new(false);let mut intent=NewDirectory::stage(f.parent.clone(),"existing").unwrap();assert!(intent.create_retaining(&original,&cancel).is_err());assert!(intent.attempted&&!intent.ack&&intent.directory.is_none());assert!(intent.create_retaining(&original,&cancel).is_err());assert_eq!(fs::read(f.path.join("existing/history")).unwrap(),b"keep");}
#[test]
fn actual_source_only_jj_git_head_is_real_and_empty_without_task_or_root_capability(){let f=Fixture::new();let original=FinalizationBudget::begin(Duration::from_secs(20)).unwrap();let cancel=AtomicBool::new(false);let mut intent=NewDirectory::stage(f.parent.clone(),"repository").unwrap();intent.create_retaining(&original,&cancel).unwrap();let directory=intent.ready().unwrap();let(mut workspace,mut repo,mut head)=(None,None,None);initialize_empty_git_retaining(&mut workspace,&mut repo,&mut head,&directory.path,&settings(),&original,&cancel).unwrap();let repo=repo.as_ref().unwrap();let head=head.as_ref().unwrap();head.validate().unwrap();let commit=repo.store().get_commit(repo.view().get_wc_commit_id(WorkspaceName::DEFAULT).unwrap()).unwrap();assert_eq!(commit.id().hex(),head.0);assert_eq!(commit.tree_ids(),&repo.store().empty_merged_tree_id());let git=repo.store().backend_impl::<GitBackend>().unwrap().git_repo_path();assert_eq!(fs::read_to_string(git.join("HEAD")).unwrap(),format!("{}\n",head.0));assert!(!directory.path.join(".rudder/engine/owner.json").exists());}
#[test]
fn cancelled_original_before_fresh_mkdir_has_no_creation_effect(){let f=Fixture::new();let original=FinalizationBudget::begin(Duration::from_secs(5)).unwrap();original.cancel();let cancel=AtomicBool::new(false);let mut intent=NewDirectory::stage(f.parent.clone(),"cancelled").unwrap();assert!(intent.create_retaining(&original,&cancel).is_err());assert!(!intent.attempted&&!intent.ack);assert!(!f.path.join("cancelled").exists());}

#[test]
fn fresh_refusal_marker_cannot_become_legacy_authority_even_when_contents_are_untrusted_data(){
    let f=Fixture::new();let repository=f.path.join("repository");fs::DirBuilder::new().mode(0o700).create(&repository).unwrap();fs::create_dir_all(repository.join(".rudder/engine")).unwrap();fs::write(repository.join(".rudder/engine/fresh-project.json"),b"not an authority receipt").unwrap();let home=f.path.join("other-home");
    let error=match EngineOwnership::acquire_in_home(&repository,NativeAuthority::Fabric,&home){Ok(_)=>panic!("marker must refuse legacy hash acquisition"),Err(error)=>error};assert!(error.to_string().contains("fresh logical"));assert!(!home.exists());assert!(!repository.join(".rudder/engine/owner.lock").exists());
}
